1	/**
2	 * **Whether the desktop-CLI update strip is up, and what dismissing it means.**
3	 *
4	 * Lifted out of `App.tsx`'s `renderUpdateBanner` because the × on that bar did
5	 * nothing in the two states people most want gone. The old rule was:
6	 *
7	 *     if (update.available && !running && !recentResult && dismissed === sig)
8	 *
9	 * — a dismissal only counted while an update was AVAILABLE and no result was
10	 * fresh. So the bar that says "Updated: updated to 2.1.267" (available is
11	 * already false, `recentResult` is true) and the bar carrying a standing
12	 * `lastError` both swallowed the tap and sat there. The signature was the
13	 * version pair alone, which cannot tell those two bars apart from each other
14	 * anyway: after an upgrade the pair does not move.
15	 *
16	 * The rule here instead: the signature names EVERY reason the bar can be up —
17	 * the version pair, the result it is reporting, the error it is carrying — and
18	 * a dismissal hides exactly that bar. A newer release, a fresh `brew upgrade`
19	 * result or a new error is a different signature and shows through on its own.
20	 * An upgrade in flight is never hidden: the × is disabled while it runs, and
21	 * the log under the bar is the only place that upgrade is visible.
22	 *
23	 * No local-module value imports here — the web unit-test layer runs this off
24	 * the TypeScript directly, so it must never reach for the DOM.
25	 */
26	import type { UpdateInfo } from "@waterplane/shared";
27	
28	/** How long a finished `brew upgrade` keeps the bar up by itself. */
29	export const RESULT_FRESH_MS = 30_000;
30	
31	export interface UpdateBarView {
32	  /** Render the bar at all. */
33	  show: boolean;
34	  /** What a × press should record — meaningless when `show` is false. */
35	  sig: string;
36	  /** The last apply finished recently enough to still be worth saying. */
37	  recentResult: boolean;
38	  /** Draw the apply button. Only while there is something to apply: after a
39	   *  clean upgrade the bar stays up for its "Updated: …" line, and an "update"
40	   *  button beside that read as if the upgrade had not happened. A run that
41	   *  moved nothing (cask lagging npm) leaves `available` true, so it stays. */
42	  canApply: boolean;
43	  /** When the fresh result goes stale and the bar must be re-read, or null. */
44	  staleAt: number | null;
45	}
46	
47	export function updateBarView(u: UpdateInfo | null, dismissed: string, now: number): UpdateBarView {
48	  if (!u) return { show: false, sig: "", recentResult: false, canApply: false, staleAt: null };
49	  const recentResult = !!u.lastResult && now - u.lastResult.at < RESULT_FRESH_MS;
50	  const canApply = !!u.available;
51	  const staleAt = recentResult ? u.lastResult!.at + RESULT_FRESH_MS : null;
52	  const sig = [u.current ?? "", u.latest ?? "", u.lastResult?.at ?? 0, u.lastError ?? ""].join("|");
53	  // Nothing to act on: no update, nothing running, no fresh result, no error.
54	  if (!u.available && !u.running && !recentResult && !u.lastError) return { show: false, sig, recentResult, canApply, staleAt };
55	  if (!u.running && dismissed === sig) return { show: false, sig, recentResult, canApply, staleAt };
56	  return { show: true, sig, recentResult, canApply, staleAt };
57	}
