1	/**
2	 * The two banners both screens draw under their header — the launcher and
3	 * the session screen mount the same pair, so they are components here rather
4	 * than two copies of a render function.
5	 *
6	 * Their state lives OUTSIDE either screen (a module store for the snooze, the
7	 * synced `dismissedUpdate` pref for the update bar): the screens unmount under
8	 * every sheet, and a dismissal that came back on the next Back would be a
9	 * banner that cannot be dismissed.
10	 */
11	import { type ReactNode, useEffect, useState } from "react";
12	import { Download, Loader, OctagonX, RefreshCcw, RotateCw, ShieldAlert, Smartphone, X } from "lucide-react";
13	import type { ClientMessage, LaunchOpts, SessionInfo, UpdateInfo } from "@waterplane/shared";
14	import { cliRestartDue, cliRestartView } from "@waterplane/shared";
15	import { askConfirm } from "../Confirm";
16	import { CantInline } from "../Unavailable";
17	import { resumeIdOf } from "../sessionFacts";
18	import { createStore, useStore } from "../sdk";
19	import { setPref, usePref } from "./prefs";
20	import { updateBarView } from "../updateBar";
21	import { track } from "../usage";
22	import { LS, lsGet, lsSet } from "../storage";
23	import { usePhoneSetup } from "../usePhoneSetup";
24	import { setupMissingText } from "../phoneSetup";
25	import { haltBannerWords, liftHalt, useHalt } from "../features/halt";
26	import { bannerView, openUpdates, useUpdatesStatus } from "../features/plugins";
27	import { armRestart, disarmRestart, useArmedRestart } from "../features/cliRestart";
28	import { Button } from "../kit/Button";
29	
30	const ICON = 16;
31	
32	/** How long the "you are on plain HTTP" banner stays hidden after a dismiss.
33	 *  A week, not forever: the failure it warns about recurs on every dropped
34	 *  tunnel, so silencing it permanently just hides a live problem. */
35	const INSECURE_SNOOZE_MS = 7 * 24 * 60 * 60 * 1000;
36	
37	// Snoozed-until timestamp, not a permanent dismissal. The consequence of
38	// staying on the insecure origin is not cosmetic — it is the app being
39	// replaced by the browser's error page every time the tunnel dies during a
40	// navigation — and a banner you can silence forever is a banner that gets
41	// silenced on the first calm day and never seen again. An old `"1"` from the
42	// permanent-dismiss version reads as "snooze from now", so nobody is
43	// re-nagged the instant they update.
44	function loadInsecureSnooze(): number {
45	  const raw = lsGet(LS.dismissInsecure);
46	  if (raw === "1") return Date.now() + INSECURE_SNOOZE_MS;
47	  return Number(raw) || 0;
48	}
49	const insecureSnooze = createStore<number>(typeof window === "undefined" ? 0 : loadInsecureSnooze());
50	
51	/**
52	 * The halt latch (`features/halt`), on every screen while it holds. Mounted in
53	 * `main.tsx` beside `UpdateBanner` for that file's reason: `App` returns early
54	 * per overlay, and a latch that stops everything must not hide behind a sheet.
55	 * Draws nothing while off. Never dismissable — the only way it goes is the
56	 * lift, because "why is nothing starting?" with no banner is what it is for.
57	 */
58	export function HaltBanner(): ReactNode {
59	  const h = useHalt();
60	  if (!h.on) return null;
61	  return (
62	    <div className="staged-bar halt-bar" role="alert">
63	      <OctagonX size={16} />
64	      <span className="staged-bar-text">{haltBannerWords(h)}</span>
65	      <Button className="staged-bar-go" type="button" onClick={liftHalt}>Lift halt</Button>
66	    </div>
67	  );
68	}
