70	/**
71	 * "You are on the plain-HTTP door, and a secure one exists."
72	 *
73	 * Everything that makes this app survive a bad link needs a service worker:
74	 * the cached app shell, OS push, the installed PWA, Background Fetch. A
75	 * service worker needs a secure context, and `http://100.x.y.z:8770` is not
76	 * one. The practical consequence is the failure this banner exists to stop —
77	 * the tunnel drops mid-sentence, the page navigates or reloads, and the
78	 * browser's own ERR_CONNECTION_TIMED_OUT page replaces the entire app: no
79	 * queue, no compose box, no way back until the link returns.
80	 *
81	 * The host already discovers its own `tailscale serve` front door and sends
82	 * it as `welcome.httpsUrl`. It was only listed in Settings → Connection,
83	 * which nobody reads while it is working. So say it where it can be acted on,
84	 * once — dismissible, and never shown when we are already secure or when
85	 * there is no HTTPS door to move to.
86	 */
87	export function InsecureBanner({ httpsUrl }: { httpsUrl: string | null }): ReactNode {
88	  const snooze = useStore(insecureSnooze);
89	  if (typeof window === "undefined" || window.isSecureContext) return null;
90	  if (!httpsUrl || Date.now() < snooze) return null;
91	  return (
92	    <div className="update-bar-wrap">
93	      <div className="update-bar">
94	        <ShieldAlert size={ICON} />
95	        <span className="update-text">
96	          Plain HTTP: no offline shell, so a dropped tunnel replaces the app with the browser's
97	          timeout page. No push and no background downloads either. Switch to the HTTPS address.
98	        </span>
99	        <Button onClick={() => { track("action:https.switch"); location.href = httpsUrl + location.pathname + location.hash; }}>
100	          switch
101	        </Button>
102	        <Button title="hide for a week — this comes back, because the problem does"
103	          onClick={() => {
104	            const until = Date.now() + INSECURE_SNOOZE_MS;
105	            insecureSnooze.set(until);
106	            lsSet(LS.dismissInsecure, String(until));
107	          }}>
108	          <X size={ICON} />
109	        </Button>
110	      </div>
111	    </div>
112	  );
113	}
114	
115	/** The phone-setup banner hides for a week after ×, for the insecure
116	 *  banner's reason: what it warns about is still true tomorrow. */
117	const SETUP_SNOOZE_MS = 7 * 24 * 60 * 60 * 1000;
118	const setupSnooze = createStore<number>(typeof window === "undefined" ? 0 : Number(lsGet(LS.dismissPhoneSetup)) || 0);
119	
120	/**
121	 * "This phone has not allowed everything the app needs in the background."
122	 *
123	 * Android grants none of it unasked, and the steps lived in two screens
124	 * (Settings, the Apps sheet) that nobody opens while things seem to work — so a
125	 * download that waits for the app to be opened, or a build nobody is told
126	 * about, looked like the app failing. Android shell only; shown while any step
127	 * is missing and it is not snoozed. Opens the checklist in Settings.
128	 */
129	export function PhoneSetupBanner({ onOpen }: { onOpen: () => void }): ReactNode {
130	  const snooze = useStore(setupSnooze);
131	  const { steps } = usePhoneSetup();
132	  const text = steps ? setupMissingText(steps) : null;
133	  if (!text || Date.now() < snooze) return null;
134	  return (
135	    <div className="update-bar-wrap">
136	      <div className="update-bar">
137	        <Smartphone size={ICON} />
138	        <span className="update-text">{text} Downloads, alerts and installs wait for the app to be opened until then.</span>
139	        <Button onClick={() => { track("action:phoneSetup.open"); onOpen(); }}>set up</Button>
140	        <Button title="hide for a week — this comes back while something is still missing"
141	          onClick={() => {
142	            const until = Date.now() + SETUP_SNOOZE_MS;
143	            setupSnooze.set(until);
144	            lsSet(LS.dismissPhoneSetup, String(until));
145	          }}>
146	          <X size={ICON} />
147	        </Button>
148	      </div>
149	    </div>
150	  );
151	}
