248	/** Which restart offers were waved away, as `<session id>|<installed version>`:
249	 *  per session and per version, so a newer install asks again. In memory — a
250	 *  reload is a fine moment to be told once more. */
251	const restartDismissed = new Set<string>();
252	/** Waved away or already sent: the compose bar's "restart first?" then stays quiet too. */
253	export function restartOfferClosed(id: string, installed: string): boolean {
254	  const key = `${id}|${installed}`;
255	  return restartDismissed.has(key) || restartSent.has(key);
256	}
257	/** Restarts already sent, same key. The button is replaced by words the moment
258	 *  it is tapped: it stayed tappable until the replacement arrived, and two taps
259	 *  were two relaunches — two claudes on one conversation. */
260	const restartSent = new Set<string>();
261	
262	export interface CliRestartBannerProps {
263	  active: SessionInfo;
264	  update: UpdateInfo | null;
265	  relaunch(s: SessionInfo, patch: Partial<LaunchOpts>): void;
266	}
267	
268	/**
269	 * **This session runs an older `claude` than the one installed** — the CLI's
270	 * own "Update installed · Restart to apply", with the restart as a button.
271	 *
272	 * The restart is `relaunch` with nothing changed: kill + create as one durable
273	 * op, resuming this exact conversation (`--resume <id>`), so the process is
274	 * replaced and the conversation is not. What it WOULD kill — a running turn, a
275	 * background agent — is named and asked about first; it never fires itself
276	 * (`shared/clirestart.ts`). **When idle** is the other answer: the person arms
277	 * it and `features/cliRestart` fires the same relaunch the first time a
278	 * restart would stop nothing.
279	 */
280	export function CliRestartBanner({ active, update, relaunch }: CliRestartBannerProps): ReactNode {
281	  const [, bump] = useState(0);
282	  const armedFor = useArmedRestart(active.id);
283	  const due = cliRestartDue(active.cliVersion, update?.current);
284	  if (!due) return null;
285	  const key = `${active.id}|${due.installed}`;
286	  if (restartDismissed.has(key)) return null;
287	  const v = cliRestartView(due, {
288	    turnActive: active.turnActive, agents: active.agents?.length, shells: active.shells, resumeId: resumeIdOf(active),
289	  });
290	  const restart = async () => {
291	    if (v.loses && !(await askConfirm({
292	      title: "Restart this session now?",
293	      lines: [
294	        `Restarting stops ${v.loses}; their work so far stays in the conversation, but what they were still doing is not finished.`,
295	        "The conversation itself reopens on the new version.",
296	      ],
297	      confirmLabel: "Restart now",
298	    }))) return;
299	    if (restartSent.has(key)) return;
300	    restartSent.add(key);
301	    bump((n) => n + 1);
302	    track("action:session.cliRestart");
303	    relaunch(active, {});
304	  };
305	  return (
306	    <div className="update-bar-wrap">
307	      <div className="update-bar">
308	        <RefreshCcw size={ICON} />
309	        <span className="update-text">
310	          {v.text}{v.loses ? ` Running now: ${v.loses}.` : ""}
311	        </span>
312	        {restartSent.has(key)
313	          ? <span className="update-text">restarting — the new session opens here</span>
314	          : v.cant
315	          ? <CantInline>can't restart here — {v.cant}</CantInline>
316	          : armedFor === due.installed
317	          ? <>
318	            <span className="update-text">restarts by itself once nothing is running</span>
319	            <Button onClick={() => disarmRestart(active.id)}>Cancel</Button>
320	          </>
321	          : <>
322	            <Button onClick={() => void restart()}>Restart, same conversation</Button>
323	            {/* The other answer to "what would it stop": wait until it stops nothing. */}
324	            <Button onClick={() => armRestart(active.id, due.installed)}>When idle</Button>
325	          </>}
326	        <Button title="hide this for this version (and cancel a restart waiting for idle) — a newer install asks again"
327	          onClick={() => { restartDismissed.add(key); disarmRestart(active.id); bump((n) => n + 1); }}>
328	          <X size={ICON} />
329	        </Button>
330	      </div>
331	    </div>
332	  );
333	}
