176	export interface CliUpdateBannerProps {
177	  update: UpdateInfo | null;
178	  liveAsk: (frame: ClientMessage, blocked?: string) => boolean;
179	  liveSend: (frame: ClientMessage, done: string, blocked?: string) => boolean;
180	}
