182	/** The desktop's `claude` update: available, running, or what the last try said. */
183	export function CliUpdateBanner({ update, liveAsk, liveSend }: CliUpdateBannerProps): ReactNode {
184	  const dismissedUpdate = usePref("dismissedUpdate");
185	  const [, bump] = useState(0);
186	  // Whether the bar is up, and what a × on it records — `updateBar.ts`, which
187	  // is where the rule is pinned by tests. It was inline here, and the × was
188	  // dead on exactly the bars people most want gone.
189	  const { show, sig, recentResult, canApply, staleAt } = updateBarView(update, dismissedUpdate, Date.now());
190	  // "Fresh" is a clock reading, and nothing else re-renders this when the 30 s
191	  // run out — without a timer the "Updated: …" bar sat there until the next
192	  // status frame, however long that took.
193	  useEffect(() => {
194	    if (staleAt == null) return;
195	    const t = setTimeout(() => bump((n) => n + 1), Math.max(0, staleAt - Date.now()) + 50);
196	    return () => clearTimeout(t);
197	  }, [staleAt]);
198	  if (!update || !show) return null;
199	  const result = update.lastResult;
200	  // A FRESH result outranks the "an update is available" headline, and that
201	  // order is the whole point: the upgrade you just pressed can run clean and
202	  // move nothing (a Homebrew cask lagging the npm release the CLI nags about),
203	  // which leaves `available` true — so the old ladder asked for an upgrade
204	  // again and never said why the last one did nothing. The reason was on the
205	  // wire the whole time; only a toast carried it, for a few seconds, on a
206	  // phone. The headline comes back on its own once the result goes stale.
207	  const text = update.running
208	    ? "Updating Claude…"
209	    : result && recentResult
210	      ? (result.ok ? `Updated: ${result.message}` : `Update failed: ${result.message}`)
211	      : update.available
212	        ? `Claude ${update.current ?? ""} → ${update.latest ?? "new"} available${update.source === "cli" ? (update.route === "brew" ? " (cask lags npm)" : " (the CLI says so)") : ""}`
213	        : `Claude ${update.current ?? "(unknown)"} · up to date`;
214	  const cls = update.running ? "running" : update.available ? "" : "idle";
215	  const showLog = (update.running || recentResult) && update.log && update.log.length > 0;
216	  return (
217	    <div className={`update-bar-wrap ${cls}`}>
218	      <div className={`update-bar ${cls}`}>
219	        <Download size={ICON} />
220	        <span className="update-text">{text}</span>
221	        {/* While the upgrade runs, check / apply / dismiss cannot do anything,
222	            so they are not drawn — the state is said in words instead of three
223	            dimmed buttons (`Unavailable.tsx`); they come back when it ends. */}
224	        {update.running ? (
225	          <span className="act-cant act-cant-inline"><Loader size={ICON} className="spin" /> running — the buttons come back when it finishes</span>
226	        ) : <>
227	          <Button onClick={() => liveAsk({ t: "update.check" }, "no connection — the update lives on the desktop and can't be checked from here")}>
228	            <RotateCw size={ICON} />
229	          </Button>
230	          {canApply && <Button onClick={() => liveSend({ t: "update.apply" }, "updating — the host restarts itself when it is done")}>
231	            {update.applyLabel ?? "update"}
232	          </Button>}
233	          <Button title="dismiss this — it comes back for a newer version, a new upgrade result or a new error"
234	            onClick={() => setPref("dismissedUpdate", sig)}>
235	            <X size={ICON} />
236	          </Button>
237	        </>}
238	      </div>
239	      {showLog && (
240	        <pre className="update-log" ref={(el) => { if (el) el.scrollTop = el.scrollHeight; }}>
241	          {update.log!.slice(-50).join("\n")}
242	        </pre>
243	      )}
244	    </div>
245	  );
246	}
